import { _decorator, Component, RigidBody, Node, Vec3 } from 'cc';
const { ccclass } = _decorator;

@ccclass('AutoSetupBallRigid')
export class AutoSetupBallRigid extends Component {
    start() {
        this.traverseAllNode(this.node.scene);
    }

    traverseAllNode(parent: Node) {
        const rigid = parent.getComponent(RigidBody);
        if (rigid) {
            // 完全放开XYZ三轴旋转
            rigid.angularFactor.set(1, 1, 1);
            rigid.linearFactor.set(1, 1, 1);

            rigid.allowSleep = false;
            rigid.useCCD = true;

            // 大幅降低旋转阻尼，旋转不会瞬间消失
            rigid.angularDamping = 0.05;
            rigid.linearDamping = 0.1;
        }

        for (const child of parent.children) {
            this.traverseAllNode(child);
        }
    }
}